<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../config/auth.php'; require_once __DIR__ . '/../services/AdminCatalogService.php'; require_once __DIR__ . '/../config/photo_status.php';
$user=requireAuth(['administrador']);$method=strtoupper($_SERVER['REQUEST_METHOD']??'GET');
try{
 if($method==='GET'){
  [$page,$limit,$offset]=adminPagination();$project=filter_var($_GET['proyecto_id']??null,FILTER_VALIDATE_INT);$line=trim((string)($_GET['linea']??''));$state=trim((string)($_GET['estado']??''));$search=trim((string)($_GET['busqueda']??''));$w=[];$p=[];
  if($project){$w[]='e.proyecto_id=?';$p[]=$project;}if($line!==''){$w[]='e.linea=?';$p[]=$line;}if($state!==''){if(!in_array($state,['activa','inactiva'],true))throw new InvalidArgumentException('Estado no válido.');$w[]='e.activo=?';$p[]=$state==='activa'?1:0;}if($search!==''){$w[]='(e.codigo LIKE ? OR e.estructura LIKE ? OR e.ubicaciones LIKE ?)';$like="%{$search}%";array_push($p,$like,$like,$like);}$where=$w?' WHERE '.implode(' AND ',$w):'';
  $c=$conn->prepare("SELECT COUNT(*) FROM postes e{$where}");$c->execute($p);$q=$conn->prepare("SELECT e.*,pr.nombre_proyecto,COALESCE(l.activa,1) linea_activa,".photoStatusSelectSql('e','fe')." FROM postes e JOIN proyectos pr ON pr.id=e.proyecto_id LEFT JOIN lineas l ON l.proyecto_id=e.proyecto_id AND l.nombre=e.linea".photoStatusJoinSql('e','fe')."{$where} ORDER BY e.proyecto_id,e.linea,e.codigo LIMIT {$limit} OFFSET {$offset}");$q->execute($p);respond(['success'=>true,'data'=>$q->fetchAll(),'total'=>(int)$c->fetchColumn(),'pagina'=>$page,'limite'=>$limit]);
 }
 $d=requestJson();
 if($method==='POST'){
  $pid=adminId($d['proyecto_id']??null,'Proyecto');$line=adminText($d['linea']??null,100,'Línea');$structure=adminText($d['estructura']??null,100,'Estructura');$requestedCode=adminText($d['codigo']??null,50,'Código',false);$code=adminText($requestedCode??($line.'-'.$structure),50,'Código');$x=adminCoordinate($d['utm_x']??null,'UTM X');$y=adminCoordinate($d['utm_y']??null,'UTM Y');$zone=adminZone($d['zona']??'19S');$location=adminText($d['ubicaciones']??null,255,'Ubicación',false);
  $conn->beginTransaction();$project=adminFetch($conn,'proyectos',$pid,true);if($project['estado']!=='activo')throw new DomainException('El proyecto debe estar activo.');$l=$conn->prepare('SELECT * FROM lineas WHERE proyecto_id=? AND nombre=? AND activa=1 FOR UPDATE');$l->execute([$pid,$line]);if(!$l->fetch())throw new DomainException('La línea no existe o está inactiva.');$dup=$conn->prepare('SELECT 1 FROM postes WHERE proyecto_id=? AND (codigo=? OR (linea=? AND estructura=?))');$dup->execute([$pid,$code,$line,$structure]);if($dup->fetchColumn())throw new DomainException('El código o la estructura ya existe en esa línea.');
  $conn->prepare('INSERT INTO postes(codigo,linea,estructura,proyecto_id,utm_x,utm_y,zona,ubicaciones,activo) VALUES(?,?,?,?,?,?,?,?,1)')->execute([$code,$line,$structure,$pid,$x,$y,$zone,$location]);$id=(int)$conn->lastInsertId();$conn->prepare('INSERT INTO poste_datos(poste_id) VALUES(?)')->execute([$id]);$after=adminFetch($conn,'postes',$id);adminAudit($conn,$user,'structure_created','estructura',['proyecto_id'=>$pid,'linea'=>$line,'poste_id'=>$id],null,$after);$conn->commit();respond(['success'=>true,'message'=>'Estructura creada correctamente','data'=>$after],201);
 }
 if($method==='PATCH'){
  $id=adminId($d['id']??null,'Estructura');$conn->beginTransaction();$before=adminFetch($conn,'postes',$id,true);$action=(string)($d['accion']??'actualizar');
  if($action==='actualizar'){$line=adminText($d['linea']??$before['linea'],100,'Línea');$structure=adminText($d['estructura']??$before['estructura'],100,'Estructura');$code=adminText($d['codigo']??$before['codigo'],50,'Código');$x=adminCoordinate($d['utm_x']??$before['utm_x'],'UTM X');$y=adminCoordinate($d['utm_y']??$before['utm_y'],'UTM Y');$zone=adminZone($d['zona']??$before['zona']);$location=adminText($d['ubicaciones']??$before['ubicaciones'],255,'Ubicación',false);$l=$conn->prepare('SELECT 1 FROM lineas WHERE proyecto_id=? AND nombre=? AND activa=1');$l->execute([$before['proyecto_id'],$line]);if(!$l->fetchColumn())throw new DomainException('La línea no existe o está inactiva.');$dup=$conn->prepare('SELECT 1 FROM postes WHERE proyecto_id=? AND id<>? AND (codigo=? OR (linea=? AND estructura=?))');$dup->execute([$before['proyecto_id'],$id,$code,$line,$structure]);if($dup->fetchColumn())throw new DomainException('El código o la estructura ya existe.');$conn->prepare('UPDATE postes SET codigo=?,linea=?,estructura=?,utm_x=?,utm_y=?,zona=?,ubicaciones=? WHERE id=?')->execute([$code,$line,$structure,$x,$y,$zone,$location,$id]);$event='structure_updated';}
  elseif(in_array($action,['desactivar','reactivar'],true)){$active=$action==='reactivar'?1:0;$conn->prepare('UPDATE postes SET activo=?,desactivado_en=IF(?=1,NULL,NOW()) WHERE id=?')->execute([$active,$active,$id]);$event=$active?'structure_enabled':'structure_disabled';}else throw new InvalidArgumentException('Acción no válida.');$after=adminFetch($conn,'postes',$id);adminAudit($conn,$user,$event,'estructura',['proyecto_id'=>$before['proyecto_id'],'linea'=>$after['linea'],'poste_id'=>$id],$before,$after);$conn->commit();respond(['success'=>true,'message'=>'Estructura actualizada.','data'=>$after]);
 }
 respond(['success'=>false,'error'=>'Método no permitido.'],405);
}catch(InvalidArgumentException $e){if($conn->inTransaction())$conn->rollBack();respond(['success'=>false,'error'=>$e->getMessage()],400);}catch(DomainException $e){if($conn->inTransaction())$conn->rollBack();respond(['success'=>false,'error'=>$e->getMessage()],409);}catch(PDOException $e){if($conn->inTransaction())$conn->rollBack();$code=(int)($e->errorInfo[1]??0);if($code===1062)respond(['success'=>false,'error'=>'El código o la estructura ya existe en esa línea.'],409);appLog('administracion','Fallo SQL en estructuras admin.',['codigo'=>$code]);respond(['success'=>false,'error'=>'No se pudo completar la operación. No se realizaron cambios.'],500);}catch(Throwable $e){if($conn->inTransaction())$conn->rollBack();appLog('administracion','Fallo en estructuras admin.',['motivo'=>$e->getMessage()]);respond(['success'=>false,'error'=>'No se pudo completar la operación. No se realizaron cambios.'],500);}
